('D078:sociology-social-anthropology', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Sociology and Social Anthropology', 'Study social relationships, institutions, culture, inequality, communities and social change through theoretical and empirical inquiry.', 1, ARRAY['UNESCO_ISCED_SOCIAL_SCIENCES', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_ISCED_SOCIAL_SCIENCES","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://unesdoc.unesco.org/in/documentViewer.xhtml?+v=2.1.196&ark=%2Fark%3A%2F48223%2Fpf0000235049%2FPDF%2F235049eng.pdf&file=%2Fin%2Frest%2FannotationSVC%2FDownloadWatermarkedAttachment%2Fattach_import_63478a00-96f0-4fee-aea7-1533d340d96f%3F_%3D235049eng.pdf&id=p%3A%3Ausmarcdef_0000235049&locale=en&multi=true","locator":"Field 03 and detailed field 031/0311–0314: social/behavioural sciences, economics, political science, psychology, sociology/cultural studies, demography and social geography; excludes physical geography and distinguishes social work, journalism and law.","supports":"The social-science umbrella contains multiple established and distinguishable disciplines with adjacent-field boundaries."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:economics-applied-analysis', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Economics and Applied Economic Analysis', 'Analyze choices, markets, production, distribution, institutions and economic outcomes using conceptual and empirical approaches.', 2, ARRAY['UNESCO_ISCED_SOCIAL_SCIENCES', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_ISCED_SOCIAL_SCIENCES","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://unesdoc.unesco.org/in/documentViewer.xhtml?+v=2.1.196&ark=%2Fark%3A%2F48223%2Fpf0000235049%2FPDF%2F235049eng.pdf&file=%2Fin%2Frest%2FannotationSVC%2FDownloadWatermarkedAttachment%2Fattach_import_63478a00-96f0-4fee-aea7-1533d340d96f%3F_%3D235049eng.pdf&id=p%3A%3Ausmarcdef_0000235049&locale=en&multi=true","locator":"Field 03 and detailed field 031/0311–0314: social/behavioural sciences, economics, political science, psychology, sociology/cultural studies, demography and social geography; excludes physical geography and distinguishes social work, journalism and law.","supports":"The social-science umbrella contains multiple established and distinguishable disciplines with adjacent-field boundaries."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:politics-governance-public-policy', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Politics, Governance and Public Policy', 'Study political institutions, public authority, policy processes, international relations, civic systems and governance outcomes.', 3, ARRAY['UNESCO_ISCED_SOCIAL_SCIENCES', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_ISCED_SOCIAL_SCIENCES","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://unesdoc.unesco.org/in/documentViewer.xhtml?+v=2.1.196&ark=%2Fark%3A%2F48223%2Fpf0000235049%2FPDF%2F235049eng.pdf&file=%2Fin%2Frest%2FannotationSVC%2FDownloadWatermarkedAttachment%2Fattach_import_63478a00-96f0-4fee-aea7-1533d340d96f%3F_%3D235049eng.pdf&id=p%3A%3Ausmarcdef_0000235049&locale=en&multi=true","locator":"Field 03 and detailed field 031/0311–0314: social/behavioural sciences, economics, political science, psychology, sociology/cultural studies, demography and social geography; excludes physical geography and distinguishes social work, journalism and law.","supports":"The social-science umbrella contains multiple established and distinguishable disciplines with adjacent-field boundaries."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:psychology-social-behaviour', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Social Behaviour and Interaction', 'Study social behaviour and interaction as a social-science subject. This area does not include clinical assessment, counselling, psychotherapy, diagnosis, psychological treatment or professional psychology licensure; those belong under the separate Psychology and Counselling domain (D064).', 4, ARRAY['UNESCO_ISCED_SOCIAL_SCIENCES', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_ISCED_SOCIAL_SCIENCES","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://unesdoc.unesco.org/in/documentViewer.xhtml?+v=2.1.196&ark=%2Fark%3A%2F48223%2Fpf0000235049%2FPDF%2F235049eng.pdf&file=%2Fin%2Frest%2FannotationSVC%2FDownloadWatermarkedAttachment%2Fattach_import_63478a00-96f0-4fee-aea7-1533d340d96f%3F_%3D235049eng.pdf&id=p%3A%3Ausmarcdef_0000235049&locale=en&multi=true","locator":"Field 03 and detailed field 031/0311–0314: social/behavioural sciences, economics, political science, psychology, sociology/cultural studies, demography and social geography; excludes physical geography and distinguishes social work, journalism and law.","supports":"The social-science umbrella contains multiple established and distinguishable disciplines with adjacent-field boundaries."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:human-geography-population', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Human Geography and Population Studies', 'Examine people, place, migration, settlement, population change and spatial patterns in social and economic life.', 5, ARRAY['UNESCO_ISCED_SOCIAL_SCIENCES', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_ISCED_SOCIAL_SCIENCES","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://unesdoc.unesco.org/in/documentViewer.xhtml?+v=2.1.196&ark=%2Fark%3A%2F48223%2Fpf0000235049%2FPDF%2F235049eng.pdf&file=%2Fin%2Frest%2FannotationSVC%2FDownloadWatermarkedAttachment%2Fattach_import_63478a00-96f0-4fee-aea7-1533d340d96f%3F_%3D235049eng.pdf&id=p%3A%3Ausmarcdef_0000235049&locale=en&multi=true","locator":"Field 03 and detailed field 031/0311–0314: social/behavioural sciences, economics, political science, psychology, sociology/cultural studies, demography and social geography; excludes physical geography and distinguishes social work, journalism and law.","supports":"The social-science umbrella contains multiple established and distinguishable disciplines with adjacent-field boundaries."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:social-research-evaluation', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Social Research and Evaluation', 'Design, conduct and interpret qualitative, quantitative and mixed-method research to answer social questions and evaluate programmes or policies.', 6, ARRAY['UNESCO_SOCIAL_SCIENCE_DEFINITION', 'UNESCO_ISCED_FIELD_DESCRIPTIONS']::text[], '[{"source_id":"UNESCO_ISCED_FIELD_DESCRIPTIONS","publisher":"UNESCO Institute for Statistics","title":"International Standard Classification of Education: Fields of Education and Training 2013 — Detailed Field Descriptions","url":"https://uis.unesco.org/sites/default/files/documents/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf","locator":"Detailed descriptions of social and behavioural science fields and their inclusions/exclusions.","supports":"Disciplinary and adjacent-field distinctions used to bound candidate areas."},{"source_id":"UNESCO_SOCIAL_SCIENCE_DEFINITION","publisher":"UNESCO Institute for Statistics","title":"Social Sciences (for R&D Data)","url":"https://uis.unesco.org/node/3080050","locator":"Definition lists psychology/cognitive sciences, economics/business, education, sociology, law, political science, social/economic geography, media/communications and other social sciences; cites Frascati Manual 2015.","supports":"Social sciences are a broad, interdisciplinary research umbrella; methods may be qualitative and quantitative."}]'::jsonb, 'medium', 'source_backed', '2026-10-12'),
('D078:computational-digital-social-science', '5175de27-0a67-58f0-a8f2-53315f5a6c81', 'D078', 'Computational and Digital Social Science', 'Use computational, digital-trace and data-intensive approaches to investigate social processes, digital technology and society, while applying social theory, research design and ethical interpretation.', 7, ARRAY['ISA_DIGITAL_SOCIOLOGY', 'UNESCO_SOCIAL_SCIENCE_DEFINITION']::text[], '[{"source_id":"ISA_DIGITAL_SOCIOLOGY","publisher":"International Sociological Association","title":"Working Group 10 — Digital Sociology","url":"https://www.isa-sociology.org/research-networks/working-groups/wg10-digital-sociology","locator":"Working group purpose: research at the intersection of digital technologies and society, advancing theoretical, empirical, methodological and socioethical knowledge.","supports":"Digital sociology is a recognized international research focus and supports a computational/digital social-science learning route."},{"source_id":"UNESCO_SOCIAL_SCIENCE_DEFINITION","publisher":"UNESCO Institute for Statistics","title":"Social Sciences (for R&D Data)","url":"https://uis.unesco.org/node/3080050","locator":"Definition lists psychology/cognitive sciences, economics/business, education, sociology, law, political science, social/economic geography, media/communications and other social sciences; cites Frascati Manual 2015.","supports":"Social sciences are a broad, interdisciplinary research umbrella; methods may be qualitative and quantitative."}]'::jsonb, 'medium', 'source_backed', '2026-10-12')
